import json


class Inventory:
    def __init__(self, stock):
        self.stock = dict(stock)
        self.reservations = {}

    def _held(self, sku):
        return sum(r["qty"] for r in self.reservations.values() if r["sku"] == sku)

    def expire(self, now):
        expired = [k for k, r in self.reservations.items()
                   if r["expire_at"] is not None and now >= r["expire_at"]]
        for k in expired:
            del self.reservations[k]

    def available(self, sku, now=None):
        if now is not None:
            self.expire(now)
        return self.stock.get(sku, 0) - self._held(sku)

    def reserve(self, key, sku, qty, now=0, ttl=None):
        if qty <= 0:
            raise ValueError("qty must be positive")
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive")
        self.expire(now)
        if key in self.reservations:
            r = self.reservations[key]
            return r["sku"] == sku and r["qty"] == qty
        if self.available(sku) < qty:
            return False
        expire_at = now + ttl if ttl is not None else None
        self.reservations[key] = {"sku": sku, "qty": qty, "expire_at": expire_at}
        return True

    def release(self, key):
        return self.reservations.pop(key, None) is not None

    def dumps(self):
        return json.dumps({
            "stock": self.stock,
            "reservations": {
                key: dict(r) for key, r in self.reservations.items()
            },
        })

    @classmethod
    def loads(cls, text):
        data = json.loads(text)
        inv = cls(data["stock"])
        inv.reservations = {
            key: dict(r) for key, r in data["reservations"].items()
        }
        return inv
